// Stop trying to build a centralized real-time brain; latency and channel silos make it impossible.
function evaluate_local_trigger(customer_id, channel, candidate_actions):
    // 1. Read a shared, asynchronous ledger of cross-channel fatigue rather than full state
    fatigue_debt = get_recent_exposure_score(customer_id)
    // 2. Pull channel-specific shadow taxes broadcast periodically by finance/planning
    channel_tax = get_global_shadow_price(channel)
    best_action = NOOP
    max_net_yield = 0
    for action in candidate_actions:
        // 3. Let channels score local utility, but penalize for shared fatigue and channel cost
        net_yield = action.local_expected_value - (action.intrusiveness * fatigue_debt) - channel_tax
        if net_yield > max_net_yield:
            best_action, max_net_yield = action, net_yield
    // 4. Default to silence: if net yield does not beat the holdout baseline, do nothing
    if max_net_yield <= holdout_threshold(customer_id):
        return NOOP
    // 5. Fire asynchronously; accept eventually consistent state over blocking coordination
    emit_async_touchpoint(customer_id, best_action)
    return best_action
